+const pptxgen = require('pptxgenjs');
+
+const { addTopBar, addFooterSource, safeOuterShadow } = require('./helpers');
+
+const slideConfig = {
+  type: 'content',
+  index: 3,
+  title: 'Depression and Anxiety Dominate: ~695 and ~687 DALYs per 100K Respectively',
+};
+
+const data = [
+  { label: 'Depressive disorders', value: 694.6 },
+  { label: 'Anxiety disorders', value: 686.5 },
+  { label: 'Schizophrenia', value: 210.2 },
+  { label: 'Bipolar disorder', value: 94.6 },
+  { label: 'Eating disorders', value: 47.5 },
+];
+
+function createSlide(pres, theme) {
+  const slide = pres.addSlide();
+  slide.background = { color: theme.bg };
+
+  addTopBar(slide, theme, {
+    title: 'Disease burden (DALYs per 100,000)',
+    slideIndex: 3,
+    slideCount: 8,
+    headerFontFace: 'Georgia',
+  });
+
+  slide.addText('Burden of disease from each category of mental illness (World, 2023)', {
+    x: 0.55,
+    y: 0.78,
+    w: 9.0,
+    h: 0.35,
+    fontFace: 'Calibri',
+    fontSize: 14,
+    color: theme.secondary,
+  });
+
+  // Chart frame
+  const frame = { x: 0.55, y: 1.15, w: 8.9, h: 3.95 };
+  slide.addShape(slide.ShapeType.roundRect, {
+    x: frame.x,
+    y: frame.y,
+    w: frame.w,
+    h: frame.h,
+    fill: { color: theme.bg },
+    line: { color: theme.accent, transparency: 40 },
+    radius: 0.18,
+    shadow: safeOuterShadow('000000', 0.12, 45, 2, 1),
+  });
+
+  const maxVal = Math.max(...data.map((d) => d.value));
+
+  const leftPad = 2.7;
+  const rightPad = 0.6;
+  const barAreaW = frame.w - leftPad - rightPad;
+  const rowH = 0.64;
+  const startY = frame.y + 0.45;
+  const labelX = frame.x + 0.25;
+  const barX = frame.x + leftPad;
+
+  // Gridline tick
+  const tickVals = [0, 200, 400, 600, 700];
+  for (const t of tickVals) {
+    const tx = barX + (t / maxVal) * barAreaW;
+    slide.addShape(slide.ShapeType.line, {
+      x: tx,
+      y: frame.y + 0.35,
+      w: 0,
+      h: frame.h - 0.7,
+      line: { color: theme.light, transparency: 55, width: 1 },
+    });
+    slide.addText(String(t), {
+      x: tx - 0.18,
+      y: frame.y + frame.h - 0.35,
+      w: 0.4,
+      h: 0.2,
+      fontFace: 'Calibri',
+      fontSize: 10,
+      color: theme.secondary,
+      align: 'center',
+    });
+  }
+
+  data.forEach((d, i) => {
+    const y = startY + i * rowH;
+    const w = (d.value / maxVal) * barAreaW;
+
+    slide.addText(d.label, {
+      x: labelX,
+      y: y + 0.12,
+      w: leftPad - 0.4,
+      h: 0.35,
+      fontFace: 'Calibri',
+      fontSize: 14,
+      color: theme.primary,
+    });
+
+    const fill = i < 2 ? theme.secondary : theme.accent;
+    slide.addShape(slide.ShapeType.roundRect, {
+      x: barX,
+      y: y + 0.1,
+      w,
+      h: 0.36,
+      fill: { color: fill },
+      line: { color: fill },
+      radius: 0.12,
+    });
+    slide.addText(d.value.toFixed(1), {
+      x: barX + w + 0.08,
+      y: y + 0.11,
+      w: 0.8,
+      h: 0.35,
+      fontFace: 'Calibri',
+      fontSize: 14,
+      color: theme.secondary,
+    });
+  });
+
+  // Key message card
+  slide.addShape(slide.ShapeType.roundRect, {
+    x: 9.55,
+    y: 1.25,
+    w: 0.0,
+    h: 0.0,
+    fill: { color: theme.bg },
+  });
+
+  slide.addShape(slide.ShapeType.roundRect, {
+    x: 9.55,
+    y: 1.25,
+    w: 0.0,
+    h: 0.0,
+    fill: { color: theme.bg },
+  });
+
+  slide.addShape(slide.ShapeType.roundRect, {
+    x: 9.55,
+    y: 1.25,
+    w: 0.0,
+    h: 0.0,
+    fill: { color: theme.bg },
+  });
+
+  slide.addShape(slide.ShapeType.roundRect, {
+    x: 9.55,
+    y: 1.25,
+    w: 0.0,
+    h: 0.0,
+    fill: { color: theme.bg },
+  });
+
+  // Right-side insight box (kept within frame width)
+  slide.addShape(slide.ShapeType.roundRect, {
+    x: 0.55,
+    y: 5.15,
+    w: 8.9,
+    h: 0.42,
+    fill: { color: theme.light, transparency: 55 },
+    line: { color: theme.light, transparency: 55 },
+    radius: 0.16,
+  });
+  slide.addText(
+    'Depressive and anxiety disorders have nearly identical DALY rates and dominate the overall mental health burden.',
+    {
+      x: 0.75,
+      y: 5.24,
+      w: 8.5,
+      h: 0.3,
+      fontFace: 'Calibri',
+      fontSize: 13,
+      color: theme.primary,
+    }
+  );
+
+  addFooterSource(slide, theme, 'Source: Our World in Data (2023). Data: IHME GBD (2025).');
+  return slide;
+}
+
+if (require.main === module) {
+  const pres = new pptxgen();
+  pres.layout = 'LAYOUT_16x9';
+  const theme = {
+    primary: '22223b',
+    secondary: '4a4e69',
+    accent: '9a8c98',
+    light: 'c9ada7',
+    bg: 'f2e9e4',
+  };
+  createSlide(pres, theme);
+  pres.writeFile({ fileName: 'slide-03-preview.pptx' });
+}
+
+module.exports = { createSlide, slideConfig };
+
*** End Patch
PATCH

